import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';
import {cinematicRegistry} from '../cinema-content.js';import {journeyMemories,cinematicContext,cinematicMusic} from '../journey-memory.js';
import {World} from '../world.js';import {defaultHero} from '../mako.js';import {unlockNode,availablePoints} from '../skill-grid-model.js';
const read=p=>JSON.parse(fs.readFileSync(new URL(p,import.meta.url))),data=read('../world.json'),lore=read('../lore-content.json'),shots=read('../../cinema/journey-manifest.json').shots,entries=cinematicRegistry(data);
test('cinematics select the installed orchestral cues for action, loss, revelation and resolution',()=>{const manifest=read('../../music/rpg/manifest.json');for(const [id,key] of [['arrival:14','cinema_loss'],['arrival:20','cinema_reveal'],['arrival:24','cinema_finale'],['guardian:20','boss'],['victory:24','credits']])assert.equal(cinematicMusic(entries.find(e=>e.id===id),manifest).id,key);assert.equal(cinematicMusic(entries.find(e=>e.kind==='technique'),manifest),null);assert.equal(cinematicMusic(entries[0],null),null);});
test('new civilian album contains only the starting companion, without future story or unknown creatures',()=>{const state={chapter:1,recruited:[0],bosses:[]};const before=JSON.stringify(state),album=journeyMemories(entries,shots,state);assert.deepEqual(album.map(e=>e.id),['crew:0']);assert.equal(JSON.stringify(state),before);});
test('legacy history becomes one replay per earned moment, preserving current videos and elder identity',()=>{const state={chapter:2,recruited:[0,2],bosses:[1],cinemaSeen:['arrival-1','creature-mossback','technique:volt:focus'],cinemaEncounters:['mossback']};const album=journeyMemories(entries,shots,state);for(const id of ['arrival:1','guardian:1','victory:1','creature:mossback','crew:2','technique:volt:focus'])assert.equal(album.filter(e=>e.id===id).length,1,id);assert.ok(!album.some(e=>e.id==='arrival-1'||e.id==='creature-mossback'||e.id==='arrival:2'||e.id==='guardian:2'||e.id==='creature:mossback-elder'));assert.ok(album.find(e=>e.id==='arrival:1').video);});
test('cinematic lore uses current visited room and never reveals an undefeated boss or future climax',()=>{const s={chapter:1,bosses:[]};assert.equal(cinematicContext(entries.find(e=>e.id==='guardian:1'),lore,s,{location:230,chapter:1}),'');assert.equal(cinematicContext(entries.find(e=>e.id==='victory:24'),lore,s,{location:230,chapter:1}),'');const e=entries.find(e=>e.id==='arrival:1');assert.ok(cinematicContext(e,lore,s,{location:230,chapter:1}).length>0);assert.equal(cinematicContext(e,lore,s,{location:135,chapter:2}),'');assert.equal(cinematicContext({...e,compact:true},lore,s,{location:230,chapter:1}),'');});
test('completed chapter resolution context matches the current lore source and remains bounded',()=>{const e=entries.find(e=>e.id==='victory:1'),text=cinematicContext(e,lore,{chapter:2,bosses:[1]},{});assert.ok(lore.plot[0].text.startsWith(text.replace(/…$/,'')));assert.ok(text.length<=190);assert.equal(cinematicContext({...e,kind:'observatory'},lore,{chapter:2,bosses:[1]},{}),'');});
test('all purchased stat paths survive a real battle level-up, JSON save, and restore',()=>{const w=new World(data),s=w.state;s.chapter=2;s.recruited=[0];Object.assign(s.heroes[0],defaultHero(0,5));s.xp=7000;for(const node of ['0:0','1:0','2:0','3:0','4:0'])assert.ok(unlockNode(s,0,node),node);const old=s.heroes[0],bonus={...old.gridBonuses},speed=old.speed;const m=data.campaign.missions[1];w.currentBattle={mission:m,scene:w.scene.location,object:{type:'patrol',bit:6,flag_address:m.flag_address}};w.winBattle();const h=s.heroes[0],base=defaultHero(0,h.level);assert.ok(h.level>5);for(const stat of ['maxHp','maxMp','power','magic'])assert.equal(h[stat],base[stat]+bonus[stat],stat);assert.equal(h.speed,speed);assert.ok(h.hp<=h.maxHp);assert.ok(availablePoints(s,0)>=0);const saved=w.save();w.restore(saved);assert.deepEqual(w.state.heroes[0].gridBonuses,bonus);assert.equal(w.state.heroes[0].speed,speed);assert.deepEqual(w.state.skillGrid[0],['0:0','1:0','2:0','3:0','4:0']);});
